1917	// placeholder rather than failing the read.
1918	func reinjectAssets(sessionTree *FetchingTree, agentType types.AgentType, transcript []byte) []byte {
1919		if !imageextract.HasPlaceholders(transcript) {
1920			return transcript
1921		}
1922		codec := imageextract.CodecFor(agentType)
1923		if codec == nil {
1924			return transcript
1925		}
1926		// No blob-integrity check is needed here: git content-addresses every asset
1927		// blob, so a corrupt/truncated fetch fails object verification and Contents()
1928		// errors out (leaving the placeholder). The manifest's sha256 is external
1929		// metadata, not a second integrity gate — and since writeAssets derives both
1930		// the blob and the sha256 from the same bytes, they can never disagree.
1931		out, err := codec.ReinjectImages(transcript, func(name string) (agent.CompactedTranscriptAsset, bool) {
1932			f, ferr := sessionTree.File(paths.AssetsDir + name)
1933			if ferr != nil {
1934				return agent.CompactedTranscriptAsset{}, false
1935			}
1936			content, cerr := f.Contents()
1937			if cerr != nil {
1938				return agent.CompactedTranscriptAsset{}, false
1939			}
1940			return agent.CompactedTranscriptAsset{Name: name, Data: []byte(content)}, true
1941		})
1942		if err != nil {
1943			return transcript
1944		}
1945		return out
1946	}
