1964			newContentHash = fmt.Sprintf("sha256:%x", sha256.Sum256(transcript.Bytes()))
1965		}
1966	
1967		// Short-circuit: if the existing content_hash.txt already matches, the
1968		// chunk entries currently in `entries` represent the same content. Leave
1969		// everything as-is and skip chunking + zlib.
1970		hashPath := checkpointSubtreePath(sessionDir, paths.ContentHashFileName)
1971		if existing, ok := entries[hashPath]; ok {
1972			if blob, err := s.repo.BlobObject(existing.Hash); err == nil {
1973				if rdr, rerr := blob.Reader(); rerr == nil {
1974					existingHash, readErr := io.ReadAll(rdr)
1975					_ = rdr.Close()
1976					if readErr == nil && string(existingHash) == newContentHash {
1977						return false, nil
1978					}
1979				}
1980			}
1981		}
1982	
1983		// Remove existing transcript files (base + any chunks)
1984		transcriptBase := checkpointSubtreePath(sessionDir, paths.TranscriptFileName)
1985		for key := range entries {
1986			if key == transcriptBase || strings.HasPrefix(key, transcriptBase+".") {
1987				delete(entries, key)
1988			}
1989		}
1990	
1991		// Resolve chunk hashes from precompute, or chunk + blob-write now.
1992		var chunkHashes []plumbing.Hash
1993		if precomputed != nil {
1994			chunkHashes = precomputed.ChunkHashes
1995		} else {
1996			chunks, err := chunkTranscript(ctx, transcript.Bytes(), agentType)
1997			if err != nil {
1998				return false, fmt.Errorf("failed to chunk transcript: %w", err)
1999			}
2000			chunkHashes = make([]plumbing.Hash, len(chunks))
2001			for i, chunk := range chunks {
2002				blobHash, err := CreateBlobFromContent(s.repo, chunk)
2003				if err != nil {
2004					return false, fmt.Errorf("failed to create transcript blob: %w", err)
2005				}
2006				chunkHashes[i] = blobHash
2007			}
2008		}
2009	
2010		// Record chunk files in the tree at v1 (full.jsonl) naming.
2011		for i, blobHash := range chunkHashes {
2012			chunkPath := checkpointSubtreePath(sessionDir, agent.ChunkFileName(paths.TranscriptFileName, i))
2013			entries[chunkPath] = object.TreeEntry{
2014				Name: chunkPath,
2015				Mode: filemode.Regular,
2016				Hash: blobHash,
2017			}
2018		}
2019	
2020		// Content-hash blob.
2021		var hashBlob plumbing.Hash
2022		if precomputed != nil {
2023			hashBlob = precomputed.ContentHashBlob
2024		} else {
2025			h, err := CreateBlobFromContent(s.repo, []byte(newContentHash))
2026			if err != nil {
2027				return false, fmt.Errorf("failed to create content hash blob: %w", err)
2028			}
2029			hashBlob = h
2030		}
2031		entries[hashPath] = object.TreeEntry{
2032			Name: hashPath,
2033			Mode: filemode.Regular,
2034			Hash: hashBlob,
2035		}
2036	
2037		// Regenerate the compact transcript from the new content so the pushed
2038		// transcript.jsonl stays current. Sanitized first to match the initial-write
2039		// path (writeTranscript), which sanitizes before compaction; this finalize path
2040		// otherwise passes raw bytes.
2041		compactBytes := SanitizeTranscriptForAgentType(agentType, transcript.Bytes())
2042		compactStart := s.writeCompactTranscript(ctx, agentType, startLine, compactBytes, sessionDir, entries)
2043	
2044		// If regeneration produced no compact transcript (failure, empty, or
2045		// oversized), drop any stale transcript.jsonl carried over from the prior
2046		// write rather than shipping it. In the OPF rewrite path the stale file is a
2047		// less-redacted compact (it predates the 8th-layer re-redaction), and its
2048		// CompactTranscriptStart would point at content that no longer matches the
2049		// re-redacted full transcript. The caller re-derives the root summary's
2050		// compact_transcript pointer from the (now absent) tree entry.
2051		if compactStart == nil {
2052			delete(entries, checkpointSubtreePath(sessionDir, paths.CompactTranscriptFileName))
2053		}
2054	
2055		// Keep the session metadata's marker consistent with the regenerated
2056		// transcript.jsonl: record the new boundary when one was produced, or clear
2057		// it (nil) when the compact transcript was dropped above.
2058		if err := s.setCompactTranscriptStart(sessionDir, compactStart, entries); err != nil {
2059			return false, fmt.Errorf("failed to update compact transcript start: %w", err)
2060		}
2061	
2062		return true, nil
2063	}
2064	
2065	// PrecomputeTranscriptBlobs chunks the given transcript and writes each chunk
2066	// plus the content-hash blob to the object store once, returning the resulting
2067	// hashes for reuse across multiple backfillTranscript calls that share the same
2068	// transcript content.
2069	func PrecomputeTranscriptBlobs(ctx context.Context, repo *git.Repository, transcript redact.RedactedBytes, agentType types.AgentType) (*PrecomputedTranscriptBlobs, error) {
2070		raw := transcript.Bytes()
2071	
2072		chunks, err := chunkTranscript(ctx, raw, agentType)
2073		if err != nil {
2074			return nil, fmt.Errorf("failed to chunk transcript: %w", err)
2075		}
2076	
2077		chunkHashes := make([]plumbing.Hash, len(chunks))
2078		for i, chunk := range chunks {
2079			h, err := CreateBlobFromContent(repo, chunk)
2080			if err != nil {
2081				return nil, fmt.Errorf("failed to create transcript blob: %w", err)
2082			}
2083			chunkHashes[i] = h
2084		}
