1953	func (s *treeWriter) replaceTranscript(ctx context.Context, transcript redact.RedactedBytes, agentType types.AgentType, startLine int, precomputed *PrecomputedTranscriptBlobs, sessionDir string, entries map[string]object.TreeEntry) (bool, error) {
1954		// Ignore precompute if invariants are violated — fall back to fresh chunking.
1955		if precomputed != nil && !precomputed.IsUsable() {
