 539	// writeStandardCheckpointEntries writes session files to numbered subdirectories and
 540	// maintains a CheckpointSummary at the root level with aggregated statistics.
 541	//
 542	// Structure:
 543	//
 544	//	basePath/
 545	//	├── metadata.json         # CheckpointSummary (aggregated stats)
 546	//	├── 1/                    # First session
 547	//	│   ├── metadata.json     # Metadata (session-specific, includes initial_attribution)
 548	//	│   ├── full.jsonl        # Raw agent transcript (CLI resume/explain)
 549	//	│   ├── transcript.jsonl  # Compact transcript scoped to this checkpoint (pushed; not yet referenced by metadata.json)
 550	//	│   ├── prompt.txt
 551	//	│   └── content_hash.txt
 552	//	├── 2/                    # Second session
 553	//	└── ...
 554	func (s *treeWriter) writeStandardCheckpointEntries(ctx context.Context, opts WriteOptions, basePath string, entries map[string]object.TreeEntry) error {
 555		// Read existing summary to get current session count
 556		var existingSummary *CheckpointSummary
 557		metadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
 558		if entry, exists := entries[metadataPath]; exists {
 559			existing, err := s.readSummaryFromBlob(entry.Hash)
 560			if err == nil {
 561				existingSummary = existing
 562			} else {
 563				logging.Debug(ctx, "writeStandardCheckpointEntries: readSummaryFromBlob failed",
 564					slog.String("metadata_path", metadataPath),
 565					slog.String("error", err.Error()))
 566			}
 567		}
 568	
 569		// Determine session index: reuse existing slot if session ID matches, otherwise append
 570		sessionIndex := s.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
 571	
 572		// Refuse if slot 0 already holds metadata for a DIFFERENT session ID.
 573		// findSessionIndex only returns 0 when existingSummary is nil (fresh write)
 574		// or when the summary claims slot 0 belongs to us — either way, the tree
 575		// actually holding session-0 metadata for someone else is a corruption /
 576		// stale-summary shape. Writing through it would overwrite data we don't
 577		// know about. Bail instead of silently clobbering.
 578		//
 579		// We read and capture BEFORE writeSessionToSubdirectory clears the subtree,
 580		// otherwise we'd only ever see our own write.
 581		if sessionIndex == 0 {
 582			if entry, exists := entries[checkpointSubtreePath(basePath, "0", paths.MetadataFileName)]; exists {
 583				if existingMeta, readErr := s.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
 584					logging.Error(ctx, "refusing checkpoint write: session 0 holds a different sessionID",
 585						slog.String("checkpoint_id", opts.CheckpointID.String()),
 586						slog.String("existing_session_id", existingMeta.SessionID),
 587						slog.String("write_session_id", opts.SessionID),
 588						slog.Bool("existing_summary_nil", existingSummary == nil))
 589					return fmt.Errorf(
 590						"refusing to overwrite session 0 of checkpoint %s: existing session ID %q differs from write session ID %q. The checkpoint tree is inconsistent (session 0 belongs to a different session than this write claims). No automated repair exists for this shape — please report it along with the output of `git ls-tree entire/checkpoints/v1 %s/`",
 591						opts.CheckpointID, existingMeta.SessionID, opts.SessionID, opts.CheckpointID.Path(),
 592					)
 593				}
 594			}
 595		}
 596	
 597		// Write session files to numbered subdirectory
 598		sessionDir := checkpointSubtreePath(basePath, strconv.Itoa(sessionIndex))
 599		sessionFilePaths, err := s.writeSessionToSubdirectory(ctx, opts, sessionDir, entries)
 600		if err != nil {
 601			return err
 602		}
 603	
 604		// Copy additional metadata files from directory if specified (to session subdirectory)
 605		if opts.MetadataDir != "" {
 606			if err := s.copyEntireMetadataDir(ctx, opts.MetadataDir, sessionDir, entries); err != nil {
 607				return fmt.Errorf("failed to copy metadata directory: %w", err)
 608			}
 609		}
 610	
 611		// Build the sessions array
 612		var sessions []SessionFilePaths
 613		if existingSummary != nil {
 614			sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
 615			copy(sessions, existingSummary.Sessions)
 616		} else {
 617			sessions = make([]SessionFilePaths, 1)
 618		}
 619		sessions[sessionIndex] = sessionFilePaths
 620	
 621		// Tripwire: an unreproduced production report had session 0 silently
 622		// replaced with a different sessionID's data. The symptom was
 623		// findSessionIndex returning 0 when it should have returned N
 624		// (append). That happens if existingSummary is nil — yet the
 625		// on-disk tree clearly had session 0's metadata. If we're writing
 626		// at sessionIndex=0 while entries has pre-existing session-0
 627		// metadata with a DIFFERENT sessionID, that's the exact bug shape.
 628		// Loud WARN so we get a log trace instead of only the symptom.
 629		if sessionIndex == 0 {
 630			path := checkpointSubtreePath(basePath, "0", paths.MetadataFileName)
 631			if entry, exists := entries[path]; exists {
 632				if existingMeta, readErr := s.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
 633					logging.Warn(ctx, "checkpoint write overwrites session 0 with a different sessionID — potential overwrite regression",
 634						slog.String("checkpoint_id", opts.CheckpointID.String()),
 635						slog.String("existing_session_id", existingMeta.SessionID),
 636						slog.String("write_session_id", opts.SessionID),
 637						slog.Bool("existing_summary_nil", existingSummary == nil))
 638				}
 639			}
 640		}
 641	
 642		// Update root metadata.json with CheckpointSummary
 643		return s.writeCheckpointSummary(opts, basePath, entries, sessions)
 644	}
