662	// startProgressDots prints dots to w every second until the returned stop function
663	// is called. The stop function prints the given suffix and a newline.
664	func startProgressDots(w io.Writer) func(suffix string) {
665		done := make(chan struct{})
666		stopped := make(chan struct{})
667		go func() {
668			defer close(stopped)
669			ticker := time.NewTicker(time.Second)
670			defer ticker.Stop()
671			for {
672				select {
673				case <-done:
674					return
675				case <-ticker.C:
676					fmt.Fprint(w, ".")
677				}
678			}
679		}()
680		return func(suffix string) {
681			close(done)
682			<-stopped // Wait for goroutine to finish before writing suffix
683			fmt.Fprintln(w, suffix)
684		}
685	}

