625	// collectCommitsSince returns non-merge commits reachable from tip but not from
626	// exclude, ordered oldest-first in topological order.
627	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
628		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
629		defer cancel()
630	
631		// cherryPickOnto computes each commit's delta against its first parent, so
632		// replaying merge commits would incorrectly re-apply changes that arrived via
633		// non-first-parent history. Limit the replay set to non-merge commits.
634		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
635		cmd.Dir = repoPath
636		output, err := cmd.Output()
637		if err != nil {
638			return nil, fmt.Errorf("git rev-list failed: %w", err)
639		}
640	
641		lines := strings.Fields(string(output))
642		if len(lines) > MaxCommitTraversalDepth {
643			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
644		}
645	
646		commits := make([]*object.Commit, 0, len(lines))
647		for _, line := range lines {
648			hash := plumbing.NewHash(line)
649			commit, commitErr := repo.CommitObject(hash)
650			if commitErr != nil {
651				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
652			}
653			if len(commit.ParentHashes) > 1 {
654				continue
655			}
656			commits = append(commits, commit)
657		}
658	
659		return commits, nil
660	}
