466	// fetchAndRebaseRefCommon fetches a remote ref and rebases local commits on top
467	// of the remote tip. Since checkpoint shards use unique paths, rebases always
468	// apply cleanly.
469	// The target can be a remote name or a URL.
470	func fetchAndRebaseRefCommon(ctx context.Context, target string, ref plumbing.ReferenceName) error {
471		// No timeout: runs under doPushRef's shared budget.
472		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
473		if err != nil {
474			return fmt.Errorf("resolve fetch target: %w", err)
475		}
476	
477		// Determine fetch refspec. When the resolved fetch target is a URL or the
478		// ref isn't a branch, fetch into a temp ref (no remote-tracking shadow);
479		// otherwise use the standard refs/remotes/<remote>/<branch> destination.
480		var fetchedRefName plumbing.ReferenceName
481		var refSpec string
482		usedTempRef := remote.IsURL(fetchTarget) || !ref.IsBranch()
483		if usedTempRef {
484			tmpRef := "refs/entire-fetch-tmp/" + strings.TrimPrefix(ref.String(), "refs/")
485			refSpec = fmt.Sprintf("+%s:%s", ref.String(), tmpRef)
486			fetchedRefName = plumbing.ReferenceName(tmpRef)
487		} else {
488			refSpec = fmt.Sprintf("+%s:refs/remotes/%s/%s", ref.String(), target, ref.Short())
489			fetchedRefName = plumbing.NewRemoteReferenceName(target, ref.Short())
490		}
491	
492		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
493		// Do NOT --unshallow here: on a shallow repo with deep history (e.g. a
494		// shared monorepo), --unshallow downloads the whole repository because
495		// git treats shallow as a global property of the clone, not per-ref.
496		// The downstream reconcile/rebase paths walk only commits visible past
497		// .git/shallow (collectCommitChain / collectCommitsSince), so the
498		// missing pre-shallow history isn't needed to produce a correct rebase.
499		// Span the fetch separately so a slow sync can be attributed to the network
500		// fetch versus the local reconcile/rebase that follows it.
501		_, fetchSpan := perf.Start(ctx, "git_fetch")
502		fetchOutput, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
503			Remote:   fetchTarget,
504			RefSpecs: []string{refSpec},
505			NoTags:   true,
506		})
507		fetchSpan.RecordError(fetchErr)
508		fetchSpan.End()
509		if fetchErr != nil {
510			return fmt.Errorf("fetch failed: %s", fetchOutput)
511		}
512	
513		repo, err := OpenRepository(ctx)
514		if err != nil {
515			return fmt.Errorf("failed to open git repository: %w", err)
516		}
517		defer repo.Close()
518	
519		// Reconcile disconnected metadata branches before rebasing.
520		// The fetch above updated the remote-tracking ref, so reconciliation
521		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
522		// this cherry-picks local commits onto remote tip, updating the local ref.
523		// If reconciliation fails, abort — proceeding to rebase on disconnected
524		// refs would silently combine unrelated histories.
525		if reconcileErr := ReconcileDisconnectedMetadataRef(ctx, repo, ref, fetchedRefName, os.Stderr); reconcileErr != nil {
526			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
527		}
528	
529		// Get local ref (re-read after potential reconciliation update)
530		localRef, err := repo.Reference(ref, true)
531		if err != nil {
532			return fmt.Errorf("failed to get local ref: %w", err)
533		}
534	
535		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
536		remoteRef, err := repo.Reference(fetchedRefName, true)
537		if err != nil {
538			return fmt.Errorf("failed to get remote ref: %w", err)
539		}
540	
541		advance := func(hash plumbing.Hash) error {
542			if err := setRefHash(repo, ref, hash); err != nil {
543				return err
544			}
545			if usedTempRef {
546				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
547			}
548			return nil
549		}
550	
551		// If local is already at or behind remote, fast-forward
552		if localRef.Hash() == remoteRef.Hash() {
553			return advance(remoteRef.Hash())
554		}
555	
556		// Find merge base
557		repoPath, err := getRepoPath(repo)
558		if err != nil {
559			return fmt.Errorf("failed to get repo path: %w", err)
560		}
561		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
562		if err != nil {
563			return fmt.Errorf("failed to find merge base: %w", err)
564		}
565	
566		// If local is ancestor of remote (merge base == local), fast-forward to remote
567		if mergeBase == localRef.Hash() {
568			if err := advance(remoteRef.Hash()); err != nil {
569				return fmt.Errorf("failed to fast-forward ref: %w", err)
570			}
571			return nil
572		}
573	
574		// Collect commits reachable from local but not from remote and cherry-pick
575		// them onto the remote tip. This preserves local-only commits even when the
576		// local metadata branch already contains old merge commits, while avoiding
577		// replaying shared ancestors older than the true merge-base.
578		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
579		if err != nil {
580			return fmt.Errorf("failed to collect local commits: %w", err)
581		}
582	
583		if len(localCommits) == 0 {
584			// No local-only commits — just point to remote
585			return advance(remoteRef.Hash())
586		}
587	
588		shallow, err := loadShallowHashes(ctx, repoPath)
589		if err != nil {
590			return fmt.Errorf("failed to load shallow boundaries: %w", err)
591		}
592	
593		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits, shallow)
594		if err != nil {
595			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
596		}
597	
598		return advance(newTip)
599	}
