2292			for _, remoteName := range remotes {
2293				refNames = append(refNames, plumbing.NewRemoteReferenceName(remoteName, s.refs.Primary.Short()))
2294			}
2295		}
2296	
2297		trees := make([]metadataTree, 0, len(refNames))
2298		kept := make([]*object.Commit, 0, len(refNames))
2299		seen := make(map[plumbing.Hash]struct{}, len(refNames))
2300		var firstErr error
2301		for _, refName := range refNames {
2302			ref, err := s.repo.Reference(refName, true)
2303			if err != nil {
2304				if firstErr == nil {
2305					firstErr = err
2306				}
2307				continue
2308			}
2309			if _, ok := seen[ref.Hash()]; ok {
2310				continue
2311			}
2312			commit, err := s.repo.CommitObject(ref.Hash())
2313			if err != nil {
2314				if firstErr == nil {
2315					firstErr = fmt.Errorf("failed to get commit object for %s: %w", refName, err)
2316				}
2317				continue
2318			}
2319			// A candidate whose commit is an ancestor of an already-kept tree
2320			// contributes nothing: every checkpoint in it is in the descendant.
2321			// This is the common shape — the local branch ahead of a tracking
2322			// ref — and skipping it saves consumers a full duplicate shard walk
2323			// on every List. Best-effort: an ancestry-check error keeps the tree
2324			// (a duplicate walk is cheaper than a missed checkpoint).
2325			if treeIsAncestorOfKept(commit, kept) {
2326				continue
2327			}
2328			tree, err := commit.Tree()
2329			if err != nil {
2330				if firstErr == nil {
2331					firstErr = fmt.Errorf("failed to get commit tree for %s: %w", refName, err)
2332				}
2333				continue
2334			}
2335			seen[ref.Hash()] = struct{}{}
2336			kept = append(kept, commit)
2337			trees = append(trees, metadataTree{tree: tree, ref: refName})
2338		}
2339		return trees, firstErr
2340	}
